insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values
  ('714dc43c-6cc8-5605-b2ba-fbaa1040e771', 'Setor Centro Histórico, Região Episcopal Nossa Senhora dos Remédios. Horários da bio do Instagram oficial, lidos só pelo trecho da busca; site da arquidiocese bloqueia leitura direta.', '{"https://www.instagram.com/catedraldemanaus/","https://arquidiocesedemanaus.org.br/area-missionaria/catedral-nossa-senhora-da-conceicao/","https://arquidiocesedemanaus.org.br/wp-content/uploads/2025/12/IAN-241-WEB.pdf"}', 'media'),
  ('731b8f6e-2019-5104-be31-3e49926ff624', 'Setor Centro Histórico, Região Episcopal Nossa Senhora dos Remédios. Horários da notícia da arquidiocese de 2019; missas de terça a quinta não confirmadas.', '{"https://arquidiocesedemanaus.org.br/2019/06/28/procissao-e-missa-marcam-o-fim-dos-festejos-da-paroquia-sagrado-coracao-de-jesus/","https://arquidiocesedemanaus.org.br/paroquia/paroquia-sagrado-coracao-de-jesus/"}', 'media'),
  ('4566dca9-ad03-5877-a163-e9de06528b45', 'Santuário arquidiocesano com paróquia; Setor Centro Histórico, Região Episcopal Nossa Senhora dos Remédios. A página da arquidiocese cita as comunidades Santa Edwiges, Santa Inês, Santa Teresinha, São João Batista e São Judas Tadeu, sem bairro.', '{"https://www.santuariosaojoseoperario.com.br/horarios-de-missa","https://www.santuariosaojoseoperario.com.br/contato","https://arquidiocesedemanaus.org.br/paroquia/santuario-sao-jose-operario/"}', 'alta'),
  ('acb79d2f-e69f-57ee-9aef-690e558c3f14', 'Setor Centro Histórico, Região Episcopal Nossa Senhora dos Remédios; paróquia salesiana. A página da arquidiocese diz horários ainda não informados; horários do trecho da bio do Instagram na busca.', '{"https://www.instagram.com/paroquiadomboscomanaus/","https://arquidiocesedemanaus.org.br/paroquia/paroquia-dom-bosco/"}', 'media'),
  ('c5640d71-b6e0-5344-ab64-81628d75e9e5', 'Setor Avenida Brasil, Região Episcopal Nossa Senhora dos Remédios. Localidade das comunidades suposta no bairro da paróquia (o site não dá endereço delas). Ponto no mapa aproximado: centro da cidade.', '{"https://psrnmanaus.com.br/horarios-de-missa/","https://psrnmanaus.com.br/como-chegar/"}', 'alta'),
  ('0fb48d37-5e35-5ce1-907d-dacfb5e7960c', 'Setor Centro Histórico, Região Episcopal Nossa Senhora dos Remédios. Página da arquidiocese lida pelo trecho da busca (leitura direta bloqueada), sem data de atualização.', '{"https://arquidiocesedemanaus.org.br/paroquia/paroquia-nossa-senhora-dos-remedios/"}', 'media'),
  ('9fdb6617-7209-5970-b603-f0a2f52cef71', 'Setor Avenida Brasil, Região Episcopal Nossa Senhora dos Remédios; frades franciscanos. Página da arquidiocese lida pelo trecho da busca, sem data.', '{"https://arquidiocesedemanaus.org.br/paroquia/paroquia-santo-antonio/"}', 'media'),
  ('ebf1a582-04b5-521c-ba15-21d3b7a5fe39', 'Setor Santa Rita de Cássia, Região Episcopal Nossa Senhora dos Navegantes. Comunidades citadas: Nossa Senhora da Luz, Mamãe Margarida (Cristo Ressuscitado), Nossa Senhora da Esperança, Nossa Senhora de Fátima, Imaculada Conceição e São Mateus, sem endereço. Fora do formato: Novena às terças às 14h30. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedemanaus.org.br/paroquia/paroquia-santissima-trindade/"}', 'media'),
  ('1ca8629a-a9fa-559e-85e1-279530e343fe', 'Setor Alvorada, Região Episcopal Nossa Senhora dos Remédios. Horários do cabeçalho do site da paróquia (rodapé de 2014-2020); a página da arquidiocese dá também missa às 7h de domingo.', '{"https://www.rainhadosapostolos-am.org.br/","https://arquidiocesedemanaus.org.br/paroquia/paroquia-nossa-senhora-rainha-dos-apostolos/"}', 'media'),
  ('080e1344-8962-59b6-bc0f-0d29cbafc24d', 'Setor Santa Rita de Cássia, Região Episcopal Nossa Senhora dos Navegantes. Página da arquidiocese lida pelo trecho da busca; sétima comunidade não apareceu. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedemanaus.org.br/paroquia/area-missionaria-santa-catarina-de-sena/","https://www.facebook.com/A.M.SantaCatarinadeSenaAm/"}', 'media'),
  ('05d55da2-b24b-598e-956b-379d84b94701', 'Setor Parque Dez, Região Episcopal Nossa Senhora dos Remédios. Site da paróquia lido só pelo trecho da busca (fora do ar na leitura direta); comunidade São João Bosco (sábado 19h) sem bairro.', '{"https://www.guadalupemanaus.com.br/?staff=nossa-senhora-de-guadalupe","https://www.guadalupemanaus.com.br/?staff-category=comunidades","https://arquidiocesedemanaus.org.br/paroquia/paroquia-nossa-senhora-de-guadalupe/"}', 'media'),
  ('ee8bf967-5813-5997-b0e6-f52aed1b9818', 'Setor Maria Mãe da Igreja, Região Episcopal Nossa Senhora dos Navegantes (setor pelo GCatholic). Sem horário publicado pela paróquia ou pela arquidiocese que se pudesse ler (só agregadores e uma página de Facebook de identificação incerta).', '{"https://arquidiocesedemanaus.org.br/area-missionaria/paroquia-nossa-senhora-do-perpetuo-socorro/","https://arquidiocesedemanaus.org.br/wp-content/uploads/2025/06/IAN-236-WEB.pdf"}', ''),
  ('2f4a9cb5-7c6b-5489-93ec-21b803ab8a76', 'Setor Santa Rita de Cássia, Região Episcopal Nossa Senhora dos Navegantes. Horários da página da arquidiocese (sem data), lida pelo trecho da busca; o Facebook da paróquia diverge. Fora do formato: A página de Facebook da paróquia diz missa todos os dias às 18h30.', '{"https://arquidiocesedemanaus.org.br/paroquia/paroquia-nossa-senhora-do-carmo/","https://www.facebook.com/pnsdocarmomanaus/"}', 'media'),
  ('fd3f49e7-c692-5e9d-b1a3-d7c38c423e1d', 'Setor Avenida Brasil, Região Episcopal Nossa Senhora dos Remédios; padres palotinos. Sem horário publicado pela paróquia ou pela arquidiocese que se pudesse ler; só agregadores.', '{"https://arquidiocesedemanaus.org.br/2019/08/15/paroquia-de-nossa-senhora-da-gloria-completa-60-anos-de-existencia/"}', ''),
  ('f047a912-d139-5c19-91f0-a6111171b3e0', 'Setor Parque Dez, Região Episcopal Nossa Senhora dos Remédios. Horários do blog da paróquia, sem data; a novena de terça pode coincidir com a missa das 19h. Ponto no mapa aproximado: centro da cidade.', '{"https://nossasenhoradelourdesam.blogspot.com/p/asas.html"}', 'media'),
  ('7891373c-e756-50d4-b31a-c413b7c63751', 'Setor Alvorada, Região Episcopal Nossa Senhora dos Remédios. Página da arquidiocese lida pelo trecho da busca, sem data. Fora do formato: Novena às terças às 19h.', '{"https://arquidiocesedemanaus.org.br/paroquia/paroquia-santa-teresinha/"}', 'media'),
  ('cd10d0b1-f1b5-5390-9c54-70480cde5e6a', 'Setor Avenida Brasil, Região Episcopal Nossa Senhora dos Remédios. Página da arquidiocese lida pelo trecho da busca, sem data; nas comunidades o texto diz celebração, que pode ser da Palavra.', '{"https://arquidiocesedemanaus.org.br/paroquia/paroquia-cristo-libertador/"}', 'media'),
  ('955e5abd-9c82-5933-ab34-982be09d13f4', 'Setor Parque Dez, Região Episcopal Nossa Senhora dos Remédios; padres scalabrinianos. Sem horário publicado que se pudesse ler.', '{"https://scalabrinianos.com/paroquia-sao-geraldo-manaus/"}', ''),
  ('a0bdb1ad-0261-553a-bfa7-8eb46291d7f3', 'Setor Padre Pedro Vignola, Região Episcopal Nossa Senhora Aparecida. Sem horário regular publicado pela paróquia ou pela arquidiocese que se pudesse ler.', '{"https://arquidiocesedemanaus.org.br/paroquia/paroquia-sao-bento/","https://arquidiocesedemanaus.org.br/wp-content/uploads/2025/08/IAN-237-WEB.pdf"}', ''),
  ('914cc74d-3401-5b7e-9be8-7c5b071d63d1', 'Setor Santa Rita de Cássia, Região Episcopal Nossa Senhora dos Navegantes (setor pelo GCatholic). Site da paróquia lido pelo trecho da busca (certificado do site impede a leitura direta), página com cerca de quatro anos.', '{"https://saopedroapostolo.org.br/informacoes-gerais/","https://arquidiocesedemanaus.org.br/paroquia/paroquia-sao-pedro-apostolo/","https://arquidiocesedemanaus.org.br/wp-content/uploads/2025/06/IAN-236-WEB.pdf"}', 'media'),
  ('3b87edef-7bec-56f4-be82-61c65c765bb0', 'Setor Santa Rita de Cássia, Região Episcopal Nossa Senhora dos Navegantes (setor pelo GCatholic). O site da paróquia dá só as missas de domingo; a paróquia tem dez núcleos (comunidades) sem horário publicado. Ponto no mapa aproximado: centro da cidade.', '{"https://www.sfassis.org.br/p/contatos.html"}', 'alta'),
  ('d09e8955-4415-5f70-99c3-c9d90b47de98', 'Setor Maria Mãe da Igreja, Região Episcopal Nossa Senhora dos Navegantes; padres redentoristas. Página da arquidiocese lida pelo trecho da busca, sem data; horários da matriz não vieram no trecho.', '{"https://arquidiocesedemanaus.org.br/paroquia/paroquia-sao-lazaro/"}', 'media'),
  ('89701173-e943-5e34-829d-587cad703bce', 'Na Zona Leste (a arquidiocese a chama São José Operário Leste, para distinguir do santuário do Centro); Setor São José Leste, Região Episcopal Nossa Senhora dos Navegantes. Página da arquidiocese lida pelo trecho da busca, sem data. Paróquia salesiana; as seis comunidades vêm do informativo da arquidiocese de janeiro de 2024.', '{"https://arquidiocesedemanaus.org.br/paroquia/paroquia-sao-jose-operario-leste/","https://arquidiocesedemanaus.org.br/wp-content/uploads/2024/01/IAN-219-WEB-_-jan-2024.pdf"}', 'media'),
  ('b1eabb60-7bb2-5ac0-bb9a-1ae1911e2cea', 'Bairro Santa Luzia (Educandos); Setor Maria Mãe da Igreja, Região Episcopal Nossa Senhora dos Navegantes. Horários do Facebook da paróquia lidos pelo trecho da busca; o blog da paróquia, mais antigo, dá domingo 6h30, 9h e 18h30. Bairro das comunidades suposto o da paróquia. Fora do formato: Dia 13 de cada mês: adoração às 18h e novena de Santa Luzia às 19h (blog da paróquia).', '{"https://www.facebook.com/paroquiasantaluziamanaus/","https://paroquiasantaluziamanaus.blogspot.com/p/horarios-de-missa.html","https://arquidiocesedemanaus.org.br/paroquia/paroquia-santa-luzia/"}', 'media'),
  ('15d19e95-30b2-51e1-b4a7-17e7ec6bd682', 'Setor Santa Rita de Cássia, Região Episcopal Nossa Senhora dos Navegantes. A página da arquidiocese diz horários ainda não informados; a sede na Rua Vinca, 37 é a da comunidade Santo Expedito. Outras comunidades: Nossa Senhora Aparecida e São Paulo Apóstolo, sem endereço.', '{"https://arquidiocesedemanaus.org.br/paroquia/area-missionaria-menino-jesus/"}', ''),
  ('c0a1baba-f54c-5dac-acd8-d2aeed28d5b7', 'Setor Santa Rita de Cássia, Região Episcopal Nossa Senhora dos Navegantes. Página da arquidiocese lida pelo trecho da busca, sem data. Fora do formato: Comunidades sem endereço na fonte: Nossa Senhora do Perpétuo Socorro, Nossa Senhora de Fátima, Menino Jesus, Jesus Bom Pastor, Jesus Cristo Libertador, Frei Galvão e Divino Espírito Santo.', '{"https://arquidiocesedemanaus.org.br/paroquia/area-missionaria-nossa-senhora-do-rosario/"}', 'media'),
  ('87f8d0a5-d6af-55f4-baef-ef80d7ef0fe1', 'Setor Parque Dez, Região Episcopal Nossa Senhora dos Remédios (setor pelo bairro, não confirmado). Página da arquidiocese lida pelo trecho da busca, sem data; outra página de 2022 dá o telefone 3307-6888.', '{"https://arquidiocesedemanaus.org.br/area-missionaria/paroquia-nossa-senhora-das-merces/"}', 'media'),
  ('ac85133a-7ba5-5cfc-8b0e-8bba6e504e6e', 'Setor Alvorada, Região Episcopal Nossa Senhora dos Remédios; a arquidiocese também a chama Área Missionária Nossa Senhora da Amazônia. Sem horário publicado que se pudesse ler.', '{"https://arquidiocesedemanaus.org.br/paroquia/area-missionaria-ponta-negra/","https://arquidiocesedemanaus.org.br/area-missionaria/area-missionaria-nossa-senhora-da-amazonia-ponta-negra/"}', ''),
  ('27d3bc86-48b0-52c1-83c7-3bd141c48080', 'Setor Padre Ruggero Ruvoletto, Região Episcopal Nossa Senhora Aparecida. A página da arquidiocese lista comunidades no Novo Israel e na Colônia Terra Nova; sem horário de missa que se pudesse ler. Fora do formato: Novena às terças às 19h.', '{"https://arquidiocesedemanaus.org.br/paroquia/area-missionaria-santa-helena/"}', ''),
  ('8eb3f219-e4e0-5cda-89e4-0115e793fb01', 'Setor Padre Pedro Vignola, Região Episcopal Nossa Senhora Aparecida. Página da arquidiocese lida pelo trecho da busca; horários das comunidades não vieram ligados a cada uma. Fora do formato: Comunidades sem endereço na fonte: Beato José de Anchieta, São João Batista, São Carlos Borromeu, São Cristóvão, Nossa Senhora de Guadalupe e Francisclariana.', '{"https://arquidiocesedemanaus.org.br/paroquia/area-missionaria-santa-monica/"}', ''),
  ('a7124353-02c3-50d8-8d81-621046413302', 'Setor Padre Pedro Vignola, Região Episcopal Nossa Senhora Aparecida. Sem horário de missa que se pudesse ler. Fora do formato: Comunidades sem endereço na fonte: Nossa Senhora do Carmo, São João Batista, Santa Clara, Sagrada Família, Sagrado Coração de Jesus, Nossa Senhora Rainha da Paz, São Paulo Apóstolo e Jesus Cristo Operário.', '{"https://arquidiocesedemanaus.org.br/paroquia/area-missionaria-sao-lucas/","https://www.instagram.com/areamissionariasaolucas/"}', ''),
  ('e493cc03-9d7d-59e0-8cbb-24a16269c44a', 'Setor Padre Pedro Vignola, Região Episcopal Nossa Senhora Aparecida; criada em 2010 de parte da Área São Paulo Apóstolo. Horários só das comunidades, sem endereço, de página antiga da arquidiocese. Fora do formato: Comunidades sem endereço na fonte: Santa Bárbara (domingo 7h30, sábado 18h), Santo Antônio (domingo 9h), São Francisco de Assis (domingo 7h30); novena do Perpétuo Socorro às terças, 19h.', '{"https://arquidiocesedemanaus.org.br/paroquia/area-missionaria-familia-de-nazare/"}', ''),
  ('778bc198-ecf8-5403-9b82-dbdad7d0a092', 'Setor Padre Pedro Vignola, Região Episcopal Nossa Senhora Aparecida; dez comunidades, só três com endereço na fonte. Página da arquidiocese lida pelo trecho da busca. Fora do formato: Missa todo dia 19 às 19h30.; Celebração todo dia 13.', '{"https://arquidiocesedemanaus.org.br/paroquia/area-missionaria-sao-paulo-apostolo/","https://arquidiocesedemanaus.org.br/2022/01/17/area-missionaria-sao-paulo-apostolo-inicia-festejos-do-padroeiro/"}', 'media'),
  ('413fb657-7ebf-5f6e-ac4b-b3bbcea46ca2', 'Setor Padre Pedro Vignola, Região Episcopal Nossa Senhora Aparecida. A sede (Rua 31) é a da comunidade Divino Espírito Santo. Página da arquidiocese lida pelo trecho da busca, sem data.', '{"https://arquidiocesedemanaus.org.br/paroquia/area-missionaria-sao-francisco-das-chagas/"}', 'media'),
  ('5e5f8bdd-dab1-56e3-8e7d-12db5a5ccf16', 'Setor Dom Luiz Soares Vieira, Região Episcopal Nossa Senhora dos Navegantes. Página da arquidiocese lida pelo trecho da busca, sem data; horários só de comunidades. Fora do formato: Comunidades sem endereço na fonte: Senhor Bom Jesus (missa 2º domingo 7h30 e 1º e 3º domingos 19h30), Cristo Operário (1º e 3º domingos 19h30), Jesus Divino Mestre (2º domingo).', '{"https://arquidiocesedemanaus.org.br/paroquia/area-missionaria-maria-imaculada/","https://areamissionariamar.wixsite.com/ammi/sobre-nos"}', ''),
  ('e33e6dcd-7668-59aa-af78-cb130fe08290', 'Setor Dom Luiz Soares Vieira, Região Episcopal Nossa Senhora dos Navegantes. Padres oblatos (OMI). Página da arquidiocese atualizada em outubro de 2026, lida pelo trecho da busca, sem horário de missa. Fora do formato: Comunidades sem endereço lido: Nossa Senhora do Rosário, Cristo Ressuscitado, Santa Luzia, Santa Teresinha, Todos os Santos, Santo Antônio, Sagrado Coração de Jesus, Perpétuo Socorro, Nossa Senhora de Fátima, Bom Jesus, São Francisco e Nossa Senhora de Guadalupe.', '{"https://arquidiocesedemanaus.org.br/paroquia/area-missionaria-ternura-de-deus/","https://arquidiocesedemanaus.org.br/wp-content/uploads/2025/08/IAN-237-WEB.pdf"}', ''),
  ('c16b184f-4c28-59a5-93c2-78a363d57c56', 'Setor Dom Luiz Soares Vieira, Região Episcopal Nossa Senhora dos Navegantes. Horários só de comunidades, de página de 2018 lida pelo trecho da busca. Fora do formato: Comunidades sem endereço na fonte (página de 2018): Santíssima Trindade (domingo 18h), Santo Antônio de Pádua (domingo 8h), São João Batista (celebração sábado 19h30). Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedemanaus.org.br/2022/12/15/area-missionaria-santa-margarida-de-cortona-acolhe-seu-novo-paroco-pe-alex/","https://arquidiocesedemanaus.org.br/paroquia/area-missionaria-santa-margarida-de-cortona/"}', ''),
  ('674c9bef-41aa-5a7e-b920-55aa12460e32', 'Setor Rio Solimões, Região Episcopal Nossa Senhora dos Navegantes. A arquidiocese a põe no Careiro; telefone não informado. Sem horário publicado pela paróquia ou pela arquidiocese que se pudesse ler (site da arquidiocese bloqueia leitura direta; busca esgotada). Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedemanaus.org.br/paroquia/area-missionaria-araca/","https://arquidiocesedemanaus.org.br/area-missionaria/area-missionaria-araca-careiro/","https://gcatholic.org/churches/brazil/105366"}', ''),
  ('d6ca6cfe-baee-560d-86f5-515766936e86', 'Setor Alvorada, Região Episcopal Nossa Senhora dos Remédios. A arquidiocese a chama Área Missionária Sagrada Família do Tarumã; criada em 2016. Página da arquidiocese lida pelo trecho da busca, sem data; o texto diz celebração.', '{"https://arquidiocesedemanaus.org.br/paroquia/area-missionaria-sagrada-familia-taruma/","https://arquidiocesedemanaus.org.br/2016/12/31/padre-charles-cunha-toma-posse-como-primeiro-paroco-da-area-missionaria-sagrada-familia-do-taruma/"}', 'media'),
  ('9abbd9ca-7f6a-5d19-938a-ff4bc80380e3', 'Setor Padre Ruggero Ruvoletto, Região Episcopal Nossa Senhora Aparecida. Padres sacramentinos; a página da congregação dá Rua Walter Pinto, 343, e telefone (92) 3654-9056. Sem horário publicado pela paróquia ou pela arquidiocese que se pudesse ler (site da arquidiocese bloqueia leitura direta; busca esgotada).', '{"https://arquidiocesedemanaus.org.br/paroquia/area-missionaria-taruma","https://sacramentinos.org.br/area-missionaria-taruma--"}', ''),
  ('c44c1d6f-b9d4-57b0-b039-7e67554df586', 'Setor Rio Negro, Região Episcopal Nossa Senhora dos Remédios. Criada em 27/12/2011 com sede no Cacau Pirêra; mais de 60 comunidades na estrada e na beira do rio; perdeu parte do território para a Área Maria Mãe da Esperança em 2025. Sem horário publicado pela paróquia ou pela arquidiocese que se pudesse ler (site da arquidiocese bloqueia leitura direta; busca esgotada). Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedemanaus.org.br/paroquia/area-missionaria-nossa-senhora-aparecida-cacau-pirera/","https://arquidiocesedemanaus.org.br/2020/12/28/area-missionaria-n-sra-aparecida-celebra-9-anos-de-evangelizacao/","https://gcatholic.org/churches/brazil/48147"}', ''),
  ('a208dcc2-60c0-5720-a04b-dad6dbf98e43', 'Setor Rios e Cachoeiras, Região Episcopal Nossa Senhora Aparecida. A página da arquidiocese diz horários ainda não informados. Quilômetros das comunidades como na fonte (estrada de Balbina). Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedemanaus.org.br/paroquia/paroquia-nossa-senhora-do-perpetuo-socorro-balbina/","https://gcatholic.org/churches/brazil/105393"}', ''),
  ('98b7f187-8f86-571d-903f-614c5bf57cc8', 'Setor Rios e Cachoeiras, Região Episcopal Nossa Senhora Aparecida. Página da arquidiocese atualizada em outubro de 2026, lida pelo trecho da busca: só missas de domingo na matriz; 28 comunidades sem horário. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedemanaus.org.br/paroquia/paroquia-sao-pedro-apostolo-rio-preto-da-eva/","https://www.instagram.com/psaopedro_apostolo/"}', 'media'),
  ('f72f34d3-b253-5886-9929-578564e386de', 'Setor não confirmado. Criada em 13/12/2025 com 22 comunidades ao longo da AM-070, do km 22 ao km 68, desmembrada da Área Nossa Senhora Aparecida; instalada na capela São José Operário da comunidade Lago do Limão (não confirmado se é a sede). Sem horário publicado pela paróquia ou pela arquidiocese que se pudesse ler (site da arquidiocese bloqueia leitura direta; busca esgotada). Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedemanaus.org.br/2026/01/13/area-missionaria-maria-mae-da-esperanca-aquela-que-traz-jesus-a-esperanca-encarnada/"}', ''),
  ('c82d0f2e-c585-5507-bfb8-63c14249f0f2', 'Setor Dom Luiz Soares Vieira, Região Episcopal Nossa Senhora dos Navegantes. Antiga Área Missionária Nossa Senhora das Vitórias (2019 área de missão, 2021 área missionária); novo título em 10/04/2025. Saiu de Ternura de Deus, Santa Maria Goretti e Imaculada Conceição. GCatholic ainda a lista como Nossa Senhora das Vitórias. Sem horário publicado pela paróquia ou pela arquidiocese que se pudesse ler (site da arquidiocese bloqueia leitura direta; busca esgotada). Ponto no mapa aproximado: centro da cidade.', '{"https://gcatholic.org/churches/brazil/105390","https://arquidiocesedemanaus.org.br/wp-content/uploads/2025/08/IAN-237-WEB.pdf"}', ''),
  ('eb9f3316-9b50-5a3c-9bf9-ff2f7693651c', 'Setor São José Leste, Região Episcopal Nossa Senhora dos Navegantes. Conhecida como Nossa Senhora das Graças do Aleixo; 75 anos em 2025; Irmãs Guanellianas e Missionárias da Caridade na paróquia. Sem horário publicado pela paróquia ou pela arquidiocese que se pudesse ler (site da arquidiocese bloqueia leitura direta; busca esgotada).', '{"https://gcatholic.org/churches/brazil/105369","https://arquidiocesedemanaus.org.br/wp-content/uploads/2025/08/IAN-237-WEB.pdf"}', ''),
  ('7b07742f-d080-5479-b6f6-12306269af86', 'Setor Parque Dez, Região Episcopal Nossa Senhora dos Remédios. Festa da padroeira em 27/11 (informativo de novembro de 2025). Sem horário publicado pela paróquia ou pela arquidiocese que se pudesse ler (site da arquidiocese bloqueia leitura direta; busca esgotada).', '{"https://gcatholic.org/churches/brazil/105320","https://arquidiocesedemanaus.org.br/wp-content/uploads/2026/05/IAN-240-WEB-nov2025.pdf"}', ''),
  ('3cb389b5-b47e-509c-8cac-ab74b3dbc5bd', 'Setor Maria Mãe da Igreja, Região Episcopal Nossa Senhora dos Navegantes. Sem horário publicado pela paróquia ou pela arquidiocese que se pudesse ler (site da arquidiocese bloqueia leitura direta; busca esgotada). Ponto no mapa aproximado: centro da cidade.', '{"https://gcatholic.org/churches/brazil/105357","https://arquidiocesedemanaus.org.br/wp-content/uploads/2025/08/IAN-231-GRAFICA.pdf"}', ''),
