  ('307960fa-b8c7-59cb-a192-68ac98419a14', 'Região da Tríplice Fronteira, sede do município; capuchinhos. Sem horário publicado pela paróquia ou diocese.', '{"https://www.xaverianos.org.br/diocese-de-alto-solimoes/745-desafios-missionarios-da-diocese-de-alto-solimoes","https://gcatholic.org/churches/brazil/61279","https://www.capuchinhos.org.br/regiao/benjamin-constant-am"}', ''),
